#include <algorithm>
#include <cmath>
#include <cstring>
#include <exception>

#include "fsr_constants.hpp"
#include "util.hpp"

// Bytecode generated by fxc at build time (see cmake/Shaders.cmake).
#include "g_shader_resample_cs.h"
#include "g_shader_fsr_easu_cs.h"
#include "g_shader_fsr_rcas_cs.h"

namespace ff::d3d11 {

namespace {

using detail::failStatus;

struct ResampleCB {
    uint32_t dstX, dstY, dstW, dstH;
    float srcX, srcY, srcW, srcH;
};
static_assert(sizeof(ResampleCB) == 32);

struct EasuCB {
    uint32_t con[16];
    uint32_t dstW, dstH, pad0, pad1;
};
static_assert(sizeof(EasuCB) == 80);

struct RcasCB {
    uint32_t con[4];
    uint32_t dstX, dstY, dstW, dstH;
};
static_assert(sizeof(RcasCB) == 32);

constexpr uint32_t ceilDiv(uint32_t a, uint32_t b) { return (a + b - 1) / b; }

class ScalerImpl final : public Scaler {
public:
    Status init(ID3D11Device* dev) {
        // Nearest and bilinear share one shader; the bound sampler (point/linear) selects the filter.
        HRESULT hr = dev->CreateComputeShader(g_shader_resample_cs, sizeof(g_shader_resample_cs), nullptr,
                                              m_resample.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateComputeShader(resample)", hr);
        hr = dev->CreateComputeShader(g_shader_fsr_easu_cs, sizeof(g_shader_fsr_easu_cs), nullptr,
                                      m_easu.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateComputeShader(fsr easu)", hr);
        hr = dev->CreateComputeShader(g_shader_fsr_rcas_cs, sizeof(g_shader_fsr_rcas_cs), nullptr,
                                      m_rcas.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateComputeShader(fsr rcas)", hr);

        D3D11_SAMPLER_DESC sd{};
        sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.ComparisonFunc = D3D11_COMPARISON_NEVER;
        sd.MaxLOD = D3D11_FLOAT32_MAX;
        sd.Filter = D3D11_FILTER_MIN_MAG_MIP_POINT;
        hr = dev->CreateSamplerState(&sd, m_point.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateSamplerState(point)", hr);
        sd.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
        hr = dev->CreateSamplerState(&sd, m_linear.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateSamplerState(linear)", hr);

        auto makeCb = [&](UINT size, ComPtr<ID3D11Buffer>& out) {
            D3D11_BUFFER_DESC bd{};
            bd.ByteWidth = size;
            bd.Usage = D3D11_USAGE_DYNAMIC;
            bd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
            bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
            return dev->CreateBuffer(&bd, nullptr, out.GetAddressOf());
        };
        hr = makeCb(sizeof(ResampleCB), m_cbResample);
        if (FAILED(hr)) return failStatus("CreateBuffer(resample cb)", hr);
        hr = makeCb(sizeof(EasuCB), m_cbEasu);
        if (FAILED(hr)) return failStatus("CreateBuffer(easu cb)", hr);
        hr = makeCb(sizeof(RcasCB), m_cbRcas);
        if (FAILED(hr)) return failStatus("CreateBuffer(rcas cb)", hr);
        m_device = dev;
        return okStatus();
    }

    Status run(ID3D11DeviceContext* ctx, ID3D11ShaderResourceView* src, Rect srcRect, ID3D11UnorderedAccessView* dst,
               Rect dstRect, const ScalerSettings& settings) override {
        try {
            return runImpl(ctx, src, srcRect, dst, dstRect, settings);
        } catch (const std::exception& e) {
            return Status::failure(std::string("Scaler::run: ") + e.what());
        } catch (...) {
            return Status::failure("Scaler::run: unknown exception");
        }
    }

private:
    template <typename T>
    static Status upload(ID3D11DeviceContext* ctx, ID3D11Buffer* cb, const T& data) {
        D3D11_MAPPED_SUBRESOURCE m{};
        const HRESULT hr = ctx->Map(cb, 0, D3D11_MAP_WRITE_DISCARD, 0, &m);
        if (FAILED(hr)) return failStatus("Map(constant buffer)", hr);
        std::memcpy(m.pData, &data, sizeof(T));
        ctx->Unmap(cb, 0);
        return okStatus();
    }

    static bool texSize(ID3D11View* view, uint32_t& w, uint32_t& h) {
        ComPtr<ID3D11Resource> res;
        view->GetResource(res.GetAddressOf());
        ComPtr<ID3D11Texture2D> tex;
        if (!res || FAILED(res.As(&tex))) return false;
        D3D11_TEXTURE2D_DESC d{};
        tex->GetDesc(&d);
        w = d.Width;
        h = d.Height;
        return true;
    }

    Status ensureIntermediate(uint32_t w, uint32_t h) {
        if (m_interTex && m_interW == w && m_interH == h) return okStatus();
        m_interTex.Reset();
        m_interSrv.Reset();
        m_interUav.Reset();
        D3D11_TEXTURE2D_DESC td{};
        td.Width = w;
        td.Height = h;
        td.MipLevels = td.ArraySize = 1;
        td.Format = DXGI_FORMAT_R8G8B8A8_UNORM; // gamma space, like the input (FSR1 expects perceptual values)
        td.SampleDesc.Count = 1;
        td.Usage = D3D11_USAGE_DEFAULT;
        td.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
        HRESULT hr = m_device->CreateTexture2D(&td, nullptr, m_interTex.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateTexture2D(FSR intermediate)", hr);
        hr = m_device->CreateShaderResourceView(m_interTex.Get(), nullptr, m_interSrv.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateShaderResourceView(FSR intermediate)", hr);
        hr = m_device->CreateUnorderedAccessView(m_interTex.Get(), nullptr, m_interUav.GetAddressOf());
        if (FAILED(hr)) return failStatus("CreateUnorderedAccessView(FSR intermediate)", hr);
        m_interW = w;
        m_interH = h;
        return okStatus();
    }

    static void unbind(ID3D11DeviceContext* ctx) {
        ID3D11ShaderResourceView* nullSrv[1] = {nullptr};
        ID3D11UnorderedAccessView* nullUav[1] = {nullptr};
        ctx->CSSetShaderResources(0, 1, nullSrv);
        ctx->CSSetUnorderedAccessViews(0, 1, nullUav, nullptr);
    }

    Status runImpl(ID3D11DeviceContext* ctx, ID3D11ShaderResourceView* src, Rect srcRect,
                   ID3D11UnorderedAccessView* dst, Rect dstRect, const ScalerSettings& settings) {
        if (!ctx || !src || !dst) return Status::failure("Scaler::run: null argument");
        if (srcRect.width == 0 || srcRect.height == 0 || dstRect.width == 0 || dstRect.height == 0)
            return Status::failure("Scaler::run: empty rectangle");
        uint32_t sw = 0, sh = 0, dw = 0, dh = 0;
        if (!texSize(src, sw, sh) || !texSize(dst, dw, dh)) return Status::failure("Scaler::run: views are not 2D textures");
        if (uint64_t{srcRect.x} + srcRect.width > sw || uint64_t{srcRect.y} + srcRect.height > sh)
            return Status::failure("Scaler::run: srcRect outside the source texture");
        if (uint64_t{dstRect.x} + dstRect.width > dw || uint64_t{dstRect.y} + dstRect.height > dh)
            return Status::failure("Scaler::run: dstRect outside the destination texture");

        Status st = okStatus();
        if (settings.algorithm == ScaleAlgorithm::Fsr1) {
            st = runFsr(ctx, src, srcRect, sw, sh, dst, dstRect, settings.sharpness);
        } else {
            const bool lin = settings.algorithm == ScaleAlgorithm::Bilinear;
            const ResampleCB cb{dstRect.x, dstRect.y, dstRect.width, dstRect.height,
                                static_cast<float>(srcRect.x), static_cast<float>(srcRect.y),
                                static_cast<float>(srcRect.width), static_cast<float>(srcRect.height)};
            st = upload(ctx, m_cbResample.Get(), cb);
            if (!st.ok()) return st;
            ctx->CSSetShader(m_resample.Get(), nullptr, 0);
            ID3D11Buffer* cbs[1] = {m_cbResample.Get()};
            ctx->CSSetConstantBuffers(0, 1, cbs);
            ID3D11SamplerState* smp[1] = {lin ? m_linear.Get() : m_point.Get()};
            ctx->CSSetSamplers(0, 1, smp);
            ID3D11ShaderResourceView* srvs[1] = {src};
            ctx->CSSetShaderResources(0, 1, srvs);
            ID3D11UnorderedAccessView* uavs[1] = {dst};
            ctx->CSSetUnorderedAccessViews(0, 1, uavs, nullptr);
            ctx->Dispatch(ceilDiv(dstRect.width, 8), ceilDiv(dstRect.height, 8), 1);
            unbind(ctx);
        }
        return st;
    }

    // Threadgroup layout: 64 threads with the AMD ARmp8x8 swizzle; each group covers a 16x16 tile (4 pixels/thread).
    Status runFsr(ID3D11DeviceContext* ctx, ID3D11ShaderResourceView* src, Rect srcRect, uint32_t texW, uint32_t texH,
                  ID3D11UnorderedAccessView* dst, Rect dstRect, float sharpness) {
        Status st = ensureIntermediate(dstRect.width, dstRect.height);
        if (!st.ok()) return st;

        EasuCB easu{};
        detail::fsrEasuConstants(easu.con, static_cast<float>(srcRect.width), static_cast<float>(srcRect.height),
                                 static_cast<float>(texW), static_cast<float>(texH), static_cast<float>(dstRect.width),
                                 static_cast<float>(dstRect.height), static_cast<float>(srcRect.x),
                                 static_cast<float>(srcRect.y));
        easu.dstW = dstRect.width;
        easu.dstH = dstRect.height;
        st = upload(ctx, m_cbEasu.Get(), easu);
        if (!st.ok()) return st;

        const float s = std::clamp(sharpness, 0.0f, 1.0f);
        RcasCB rcas{};
        detail::fsrRcasConstants(rcas.con, (1.0f - s) * 2.0f); // stops: 0 = sharpest
        rcas.dstX = dstRect.x;
        rcas.dstY = dstRect.y;
        rcas.dstW = dstRect.width;
        rcas.dstH = dstRect.height;
        st = upload(ctx, m_cbRcas.Get(), rcas);
        if (!st.ok()) return st;

        const uint32_t gx = ceilDiv(dstRect.width, 16), gy = ceilDiv(dstRect.height, 16);

        // Pass 1: EASU, source -> intermediate.
        ctx->CSSetShader(m_easu.Get(), nullptr, 0);
        ID3D11Buffer* cb1[1] = {m_cbEasu.Get()};
        ctx->CSSetConstantBuffers(0, 1, cb1);
        ID3D11SamplerState* smp[1] = {m_linear.Get()};
        ctx->CSSetSamplers(0, 1, smp);
        ID3D11ShaderResourceView* srv1[1] = {src};
        ctx->CSSetShaderResources(0, 1, srv1);
        ID3D11UnorderedAccessView* uav1[1] = {m_interUav.Get()};
        ctx->CSSetUnorderedAccessViews(0, 1, uav1, nullptr);
        ctx->Dispatch(gx, gy, 1);
        unbind(ctx);

        // Pass 2: RCAS, intermediate -> dst at dstRect.xy.
        ctx->CSSetShader(m_rcas.Get(), nullptr, 0);
        ID3D11Buffer* cb2[1] = {m_cbRcas.Get()};
        ctx->CSSetConstantBuffers(0, 1, cb2);
        ID3D11ShaderResourceView* srv2[1] = {m_interSrv.Get()};
        ctx->CSSetShaderResources(0, 1, srv2);
        ID3D11UnorderedAccessView* uav2[1] = {dst};
        ctx->CSSetUnorderedAccessViews(0, 1, uav2, nullptr);
        ctx->Dispatch(gx, gy, 1);
        unbind(ctx);
        return okStatus();
    }

    ComPtr<ID3D11Device> m_device;
    ComPtr<ID3D11ComputeShader> m_resample, m_easu, m_rcas;
    ComPtr<ID3D11SamplerState> m_point, m_linear;
    ComPtr<ID3D11Buffer> m_cbResample, m_cbEasu, m_cbRcas;
    ComPtr<ID3D11Texture2D> m_interTex;
    ComPtr<ID3D11ShaderResourceView> m_interSrv;
    ComPtr<ID3D11UnorderedAccessView> m_interUav;
    uint32_t m_interW = 0, m_interH = 0;
};

} // namespace

Result<std::unique_ptr<Scaler>> Scaler::create(ID3D11Device* device) {
    using R = Result<std::unique_ptr<Scaler>>;
    if (!device) return R::failure("Scaler::create: null device");
    try {
        auto s = std::make_unique<ScalerImpl>();
        const Status st = s->init(device);
        if (!st.ok()) return R::failure(st.error());
        return R::success(std::move(s));
    } catch (const std::exception& e) {
        return R::failure(std::string("Scaler::create: ") + e.what());
    }
}

} // namespace ff::d3d11
